use dioxus::prelude::*;

/// Inline SVG icon set. Replaces the FontAwesome webfont CDN stylesheet:
/// nothing render-blocking, no webfont download, no third-party request —
/// and only the glyphs this site actually uses ship in the bundle.
///
/// Glyph path data from Font Awesome Free 6.4.0 (fontawesome.com), used
/// under the Creative Commons Attribution 4.0 license.
///
/// Usage: `Icon { icon: "github", class: "text-xl" }` — the glyph inherits
/// font-size via the 1em box and color via currentColor, mirroring the old
/// `<i class="fa-…">` sizing.
#[component]
pub fn Icon(
    /// Icon key — see [`ICONS`].
    icon: &'static str,
    /// Extra classes (size/color utilities) appended to the svg.
    class: Option<&'static str>,
) -> Element {
    let (view_box, d) = match ICONS.iter().find(|(key, _, _)| *key == icon) {
        Some((_, view_box, d)) => (*view_box, *d),
        None => ("0 0 512 512", ""),
    };
    let class = format!(
        "inline-block h-[1em] w-[1em] align-[-0.125em] fill-current {}",
        class.unwrap_or_default()
    );
    rsx! {
        svg {
            view_box,
            class,
            "aria-hidden": "true",
            "focusable": "false",
            path { d, fill: "currentColor" }
        }
    }
}

